    Bug 1944274 - Break out of Mapi sending if we're shutting down so we don't end up spinning event loop until we crash. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D235764

diff --git a/mailnews/mapi/mapihook/src/msgMapiHook.cpp b/mailnews/mapi/mapihook/src/msgMapiHook.cpp
index d218ae3af2d..aaca5c14845 100644
--- a/mailnews/mapi/mapihook/src/msgMapiHook.cpp
+++ b/mailnews/mapi/mapihook/src/msgMapiHook.cpp
@@ -306,8 +306,11 @@ nsresult nsMapiHook::BlindSendMail(unsigned long aSession,
   if (WeAreOffline()) return NS_OK;

   // Wait for OnStopSending to be called.
-  mozilla::SpinEventLoopUntil("nsIMsgCompose::SendMsg is async"_ns,
-                              [=]() { return sendListener->IsDone(); });
+  mozilla::SpinEventLoopUntil("nsIMsgCompose::SendMsg is async"_ns, [=]() {
+    bool shutdownInProgress = false;
+    accountManager->GetShutdownInProgress(&shutdownInProgress);
+    return sendListener->IsDone() || shutdownInProgress;
+  });

   return rv;
 }
